head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[input > P > escape]<br/>placeholder 속성값에 대한 이스케이프 처리 여부를 설정합니다.",
    "validation" : [        
        "미설정 시 홑따옴표(') 문자를 이스케이프 처리합니다.",
        "false 설정 시 홑따옴표(') 문자를 이스케이프 처리 하지 않습니다.",
        "true 설정 시 홑따옴표(') 문자를 이스케이프 처리합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 기존 target 있으면 삭제
    if (typeof target2 !== 'undefined') {
        target2.remove();
    }

    // 조건 설정   
    let properties = {    
        placeholder: con_placeholder.getValue(),
        escape: con_escape.getText(),
        style: 'width:200px;height:30px;',
    };

    let cList = $c.gcm.createCList(properties);    

    $c.gcm.createEmptyInput(cList, 'ev:onclick="scwin.target1_onclick"');
}



scwin.target1_onclick = function (e) {
    // placeholder 확인
    rtn = target1.render.placeholder
    wf_body_bottom.getObj("scwin").setReturnValue("placeholder : " + rtn);    

    // // text 확인
    // rtn = target1.render.value
    // wf_body_bottom.getObj("scwin").setReturnValue("text : " + rtn);    

    // // tooltip 확인
    // let objTooltip = document.querySelector('.w2balloonTip_label');    

    // if (objTooltip) {
    //     wf_body_bottom.getObj("scwin").setReturnValue("tooltip : " + objTooltip.textContent);
    // }       
}
